def refs(): return [{**s,"locator":f"{s['title']}；僅取人物意願、需要與情緒表達能力方向。","observedPattern":"參照公開英文試題的生活語境、情緒線索與說話者意圖判讀層次；題幹、選項與答案全部重新編寫。","reuseDecision":"pattern-only","status":"recorded","subject":"english","locatorLevel":"paper"} for s in SOURCES]
def make(i,prompt,opts,ans,exp,strat,steps,diff): return {"id":f"question-english-performance-2-iv-5-{i}","subject":"english","type":"single-choice","prompt":prompt,"options":[{"id":k,"text":v} for k,v in opts.items()],"knowledgeIds":[KG],"difficulty":diff,"answer":{"value":ans,"explanation":exp},"provenance":{"origin":"original","license":"All rights reserved","sourceUrl":SOURCES[0]["url"],"sourceLocator":"三份公開英文試題僅供能力方向研究；未複製原題、選項、文章或答案。","authoringNote":"依官方課綱 KG 與公開英文試題的需求、意願與感受表達能力方向獨立編寫；待第二輪 AI／Terra 內容複核。"},"reviewStatus":"draft","updatedAt":"2026-09-09","lessonId":LESSON,"examPatternRefs":refs(),"solutionStrategy":strat,"solutionSteps":steps}
Q=[
make(1,"The classroom is hot, and Ken says, 'I need some fresh air.' What does Ken express?",{"A":"A need for fresh air","B":"A plan to buy a new desk","C":"A dislike of all science","D":"A request to cancel the semester"},"A","I need directly states a need, and fresh air identifies what Ken requires because the room is hot.","Use the verb need to distinguish a current requirement from a plan or general opinion.",["Notice the situation: the classroom is hot.","Find Ken's key verb: need.","Identify the object of the need: fresh air.","Reject unrelated desk, science, and semester claims.","Choose A because it restates the expressed need."],"easy"),
make(2,"Lina says, 'I would like to join the art club, but I have piano practice on Tuesdays.' What is Lina's intention?",{"A":"She wants to join but has a schedule conflict.","B":"She refuses all art activities forever.","C":"She has already left the art club.","D":"She needs a new piano today."},"A","I would like to join expresses willingness, while piano practice on Tuesdays creates a conflict rather than a complete refusal.","Read the desire clause and the contrast clause together to distinguish willingness from ability at a specific time.",["Identify Lina's desire: join the art club.","Notice I would like to as a willingness expression.","Read the contrast: piano practice on Tuesdays.","Interpret the conflict as schedule-specific, not permanent refusal.","Choose A because it includes both intention and limitation."],"medium"),
make(3,"After carrying boxes upstairs, Marco says, 'I'm exhausted. I need to sit down.' Which feeling does he show?",{"A":"Extreme tiredness","B":"Excitement about a concert","C":"Anger at a map","D":"Confidence about a test"},"A","Exhausted means extremely tired, and needing to sit after carrying boxes supports that feeling.","Combine the adjective with the physical context before selecting the emotional or physical state.",["Identify the activity: carrying boxes upstairs.","Use exhausted as a strong tiredness clue.","Connect needing to sit with physical fatigue.","Reject excitement, anger, and confidence because no evidence supports them.","Choose A because it matches both words and situation."],"easy"),
make(4,"Nora sees the surprise party and says, 'Wow! I didn't expect this!' What does she probably feel?",{"A":"Surprised","B":"Bored","C":"Hungry for directions","D":"Certain the party was canceled"},"A","Wow and I didn't expect this show that the event is unexpected, so Nora is surprised.","Use the exclamation and expectation statement as direct emotional evidence.",["Identify the event: Nora sees a surprise party.","Notice Wow as an emotional reaction.","Interpret didn't expect this as evidence of surprise.","Remove boredom and claims about directions or cancellation.","Select A because both clues point to surprise."],"easy"),
make(5,"A: Do you want to watch the documentary? B: Yes, I'd love to. What does B express?",{"A":"Strong willingness","B":"A need to leave immediately","C":"Fear of documentaries","D":"A refusal to choose"},"A","I'd love to is an enthusiastic way to express willingness to do the suggested activity.","Match the answer to the invitation and interpret love as enthusiasm in this context, not literal affection.",["Identify the invitation: watch the documentary.","Read B's response: Yes, I'd love to.","Interpret the response as eager willingness.","Reject leaving, fear, and refusal because the answer begins Yes.","Choose A because it captures the strength of the willingness."],"easy"),
make(6,"The road is icy, so Priya says, 'I'm worried about riding my bike home.' What feeling does she communicate?",{"A":"Concern about safety","B":"Pride in a new bike","C":"Joy about the ice","D":"A wish to race everyone"},"A","I'm worried and the icy road indicate concern about the safety of riding home.","Use the environmental clue to interpret the feeling phrase in its actual situation.",["Identify the risk: the road is icy.","Find the feeling phrase: I'm worried.","Connect worry with the safety of riding home.","Reject pride, joy, and racing because they contradict the context.","Choose A because it states the supported concern."],"medium"),
make(7,"A: Would you like more soup? B: No, thanks. I'm full. What does B mean?",{"A":"B does not want more soup because B has eaten enough.","B":"B wants three more bowls.","C":"B has not tasted the soup.","D":"B is asking for a different restaurant."},"A","No, thanks is a polite refusal, and I'm full explains that B has eaten enough.","Combine the response marker with the reason instead of treating No as rude or incomplete.",["Identify the offer: more soup.","Read B's reply: No, thanks.","Interpret it as a polite refusal.","Use I'm full as the reason for refusing.","Choose A because it includes both intention and explanation."],"easy"),
make(8,"After receiving the scholarship email, David says, 'I can't believe it—I worked for this all year!' Which combination best describes his response?",{"A":"Surprise and pride","B":"Boredom and refusal","C":"Fear of doing no work","D":"Confusion about the weather"},"A","I can't believe it shows surprise, while worked for this all year supports pride in the achievement.","Read the two clauses as two different emotional clues and combine them.",["Identify the event: David receives a scholarship.","Interpret I can't believe it as surprise.","Interpret the year of effort as evidence of pride or satisfaction.","Reject boredom, refusal, fear of work, and weather.","Select A because it preserves both supported feelings."],"hard"),
make(9,"A: We need a volunteer to read the first paragraph. B: I can do it. What does B communicate?",{"A":"Willingness to take the task","B":"A need for a new paragraph","C":"An inability to read","D":"A refusal to help the group"},"A","I can do it accepts the volunteer task and communicates willingness or ability to take it.","Connect the response to the immediately stated task and distinguish acceptance from refusal.",["Identify the task: read the first paragraph.","Notice the group needs a volunteer.","Interpret I can do it as accepting the task.","Reject need, inability, and refusal because the statement offers action.","Choose A because it states the communicated willingness."],"easy"),
make(10,"A: How do you feel about moving to a new school? B: I'm nervous, but I hope to make friends soon. What is the best summary?",{"A":"B feels nervous but remains hopeful about making friends.","B":"B is completely relaxed and wants no friends.","C":"B is angry because the school is closed.","D":"B has already made every friend at the new school."},"A","I'm nervous states concern, while I hope to make friends soon shows a positive expectation; A includes both sides.","Use the contrast marker but to combine the present feeling with the future hope.",["Identify the change: moving to a new school.","Record the current feeling: nervous.","Record the future hope: make friends soon.","Use but to keep both ideas rather than choosing only one.","Select A because it accurately summarizes the mixed feeling."],"hard"),
]
